#!/usr/bin/env python3
"""
Round 129b (culprits-tiles-more), 2 October 2026. Upload after round128b_tiles.py.

- scripts/iuu_vessels.py: last known positions written as a port or sea are
  placed by Nominatim; history rows no longer read as labels.
- scripts/medical_culprits.py: the settlements table read with its merged
  cells, so the company column is the company.
- scripts/nusantara_health.py: each layer is also asked where its own data is.

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/iuu_vessels.py': '',
    'scripts/medical_culprits.py': '',
    'scripts/nusantara_health.py': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
